&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Judgment:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;E&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;valuat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; information and mak&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;decisions in complex situations&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Adaptability:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;L&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;earn, adjust, and stay effective through change&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Connection:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;C&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;ommunicat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, collaborat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, and build trust&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;To learn more about why these skills matter and what the data shows about thriving through change, read this&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot; target=&quot;_blank&quot; data-target-href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot;&gt;blog post&lt;/a&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;from&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt; our Chief People Officer, Melanie Rosenwasser.&lt;/span&gt;&lt;/p&gt;
&lt;h2 data-usually-unique-id=&quot;044234883370604133046166&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zqz90zkz74zz76zeez80zz68zz89zz88zvqz86zuxlz73zexxz80zz73z6d6z72zz79zsz77z&quot;&gt;Compensation&lt;/span&gt;&lt;/h2&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Ireland Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;€40.800&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;€55.200 EUR&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;Role Description&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Dropbox is looking for a Senior Program Manager, Customer Programs to lead complex, cross-functional programs that deepen how we engage, learn from, and deliver value to our customers.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;This role sits at the intersection of customers, GTM, and Product. You will lead programs that bring customers into important moments across the product and customer lifecycle - from early product learning and customer validation to launches, adoption, advocacy, and strategic customer engagement. You’ll ensure we are engaging the right customers for the right purpose, creating a coordinated experience across Dropbox, and turning what we learn into clear actions for the business.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;This is a senior individual-contributor role with significant autonomy and executive visibility. You’ll take high-priority initiatives that often span multiple functions, have evolving requirements, or lack an established operating model and turn them into well-run programs. You’ll define the objective, determine the right program approach, align stakeholders, establish ownership and decision points, manage dependencies and risks, and drive execution through measurable outcomes.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;A critical part of the role is representing the customer experience across the entire program, not simply coordinating internal teams. You’ll think deliberately about who we engage, why we are engaging them, what we are asking of them, how Dropbox shows up across touchpoints, and how we close the loop on their participation. The customer should experience one coordinated Dropbox program even when many internal teams are involved behind the scenes.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;You’ll work across Sales, Customer Success, Product, Research, Design, Engineering, Product Marketing, Customer Marketing, Analytics, and other teams depending on the program. Over time, you’ll also help Dropbox build more repeatable ways to run customer programs - creating playbooks and operating mechanisms that allow successful approaches to scale without creating unnecessary process.&lt;/span&gt;&lt;/p&gt;
&lt;h2 class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;Responsibilities&lt;/span&gt;&lt;/h2&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Lead complex customer programs end-to-end, translating ambiguous business priorities into clear objectives, operating plans, milestones, decision points, owners, risks, and measurable outcomes.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Create a coordinated customer experience across Dropbox by partnering with Sales, Customer Success, Product, and other teams to ensure customers receive clear expectations, thoughtful engagement, and appropriate follow-through.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Lead large cross-functional teams through competing priorities, dependencies, and ambiguity, driving decisions and accountability without relying on formal authority.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Connect customer signal to action by ensuring feedback, behavior, and program results reach the right Product and GTM owners and translate into decisions, changes, or clearly documented next steps.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Build practical and scalable program infrastructure - including workbacks, decision rights, readiness criteria, status mechanisms, risk/escalation paths, measurement, and reusable playbooks - while avoiding unnecessary process.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Provide clear executive-level synthesis of program health, customer signal, risks, tradeoffs, decisions, and recommendations.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;Requirements&lt;/span&gt;&lt;/h2&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;8+ years of experience in program management, customer programs, strategy &amp;amp; operations, GTM operations, product operations, or a related field, with demonstrated ownership of complex cross-functional programs.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Demonstrated ability to take a highly ambiguous initiative from problem definition through execution, measurement, and outcome, operating independently with limited direction.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience leading programs involving customers or customer-facing teams, with strong judgment around customer selection, engagement, communications, expectations, and experience.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Demonstrated ability to coordinate multiple senior stakeholders and functions with different priorities, dependencies, and decision rights while maintaining momentum and accountability.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Strong operating judgment: able to determine the appropriate level of structure for a problem, make tradeoffs, simplify where possible, and build repeatable mechanisms where needed.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Strong written and verbal communication skills, including the ability to synthesize complex qualitative and quantitative information into concise recommendations, decisions, and executive updates.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Demonstrated ability to operate as a hands-on senior IC, moving comfortably between strategic problem-solving and the detailed execution required to deliver a program successfully.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Preferred Qualifications&lt;/h2&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience leading customer programs involving early product feedback, beta/early-access programs, customer validation, product launches, adoption, advocacy, or strategic customer engagement.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience working across both Product/EPD and GTM organizations and translating customer needs and business requirements between the two.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience building a new program or operating model and scaling it across products, customer segments, or business priorities.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience in B2B SaaS, enterprise software, collaboration/productivity technology, or another complex technology environment.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience using AI and automation to improve program execution, customer insights, synthesis, reporting, or operating efficiency.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Durable Skills&lt;/h2&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;AI fluency means using these tools to &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;em&gt;amplify&lt;/em&gt;&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; human judgment, not replace it. We believe people with these skills will thrive as work and technology&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;continue to evolve:&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Awareness:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;U&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;nderstand &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;yourself&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; and others&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Judgment:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;E&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;valuat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; information and mak&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;decisions in complex situations&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Adaptability:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;L&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;earn, adjust, and stay effective through change&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Connection:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;C&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;ommunicat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, collaborat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, and build trust&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;To learn more about why these skills matter and what the data shows about thriving through change, read this&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot; target=&quot;_blank&quot; data-target-href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot;&gt;blog post&lt;/a&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;from&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt; our Chief People Officer, Melanie Rosenwasser.&lt;/span&gt;&lt;/p&gt;
&lt;h2 data-usually-unique-id=&quot;044234883370604133046166&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zqz90zkz74zz76zeez80zz68zz89zz88zvqz86zuxlz73zexxz80zz73z6d6z72zz79zsz77z&quot;&gt;Compensation&lt;/span&gt;&lt;/h2&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Canada Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$128,400&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$173,700 CAD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;Role Description&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Dropbox is looking for a Senior Program Manager, Customer Programs to lead complex, cross-functional programs that deepen how we engage, learn from, and deliver value to our customers.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;This role sits at the intersection of customers, GTM, and Product. You will lead programs that bring customers into important moments across the product and customer lifecycle - from early product learning and customer validation to launches, adoption, advocacy, and strategic customer engagement. You’ll ensure we are engaging the right customers for the right purpose, creating a coordinated experience across Dropbox, and turning what we learn into clear actions for the business.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;This is a senior individual-contributor role with significant autonomy and executive visibility. You’ll take high-priority initiatives that often span multiple functions, have evolving requirements, or lack an established operating model and turn them into well-run programs. You’ll define the objective, determine the right program approach, align stakeholders, establish ownership and decision points, manage dependencies and risks, and drive execution through measurable outcomes.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;A critical part of the role is representing the customer experience across the entire program, not simply coordinating internal teams. You’ll think deliberately about who we engage, why we are engaging them, what we are asking of them, how Dropbox shows up across touchpoints, and how we close the loop on their participation. The customer should experience one coordinated Dropbox program even when many internal teams are involved behind the scenes.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;You’ll work across Sales, Customer Success, Product, Research, Design, Engineering, Product Marketing, Customer Marketing, Analytics, and other teams depending on the program. Over time, you’ll also help Dropbox build more repeatable ways to run customer programs - creating playbooks and operating mechanisms that allow successful approaches to scale without creating unnecessary process.&lt;/span&gt;&lt;/p&gt;
&lt;h2 class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;Responsibilities&lt;/span&gt;&lt;/h2&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Lead complex customer programs end-to-end, translating ambiguous business priorities into clear objectives, operating plans, milestones, decision points, owners, risks, and measurable outcomes.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Create a coordinated customer experience across Dropbox by partnering with Sales, Customer Success, Product, and other teams to ensure customers receive clear expectations, thoughtful engagement, and appropriate follow-through.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Lead large cross-functional teams through competing priorities, dependencies, and ambiguity, driving decisions and accountability without relying on formal authority.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Connect customer signal to action by ensuring feedback, behavior, and program results reach the right Product and GTM owners and translate into decisions, changes, or clearly documented next steps.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Build practical and scalable program infrastructure - including workbacks, decision rights, readiness criteria, status mechanisms, risk/escalation paths, measurement, and reusable playbooks - while avoiding unnecessary process.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Provide clear executive-level synthesis of program health, customer signal, risks, tradeoffs, decisions, and recommendations.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;Requirements&lt;/span&gt;&lt;/h2&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;8+ years of experience in program management, customer programs, strategy &amp;amp; operations, GTM operations, product operations, or a related field, with demonstrated ownership of complex cross-functional programs.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Demonstrated ability to take a highly ambiguous initiative from problem definition through execution, measurement, and outcome, operating independently with limited direction.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience leading programs involving customers or customer-facing teams, with strong judgment around customer selection, engagement, communications, expectations, and experience.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Demonstrated ability to coordinate multiple senior stakeholders and functions with different priorities, dependencies, and decision rights while maintaining momentum and accountability.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Strong operating judgment: able to determine the appropriate level of structure for a problem, make tradeoffs, simplify where possible, and build repeatable mechanisms where needed.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Strong written and verbal communication skills, including the ability to synthesize complex qualitative and quantitative information into concise recommendations, decisions, and executive updates.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Demonstrated ability to operate as a hands-on senior IC, moving comfortably between strategic problem-solving and the detailed execution required to deliver a program successfully.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Preferred Qualifications&lt;/h2&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience leading customer programs involving early product feedback, beta/early-access programs, customer validation, product launches, adoption, advocacy, or strategic customer engagement.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience working across both Product/EPD and GTM organizations and translating customer needs and business requirements between the two.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience building a new program or operating model and scaling it across products, customer segments, or business priorities.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience in B2B SaaS, enterprise software, collaboration/productivity technology, or another complex technology environment.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80zsz86z2n7z83zbz85zez68zz66znel3z82zz89z5z66zz85zz85z0ce6z85zz89zs5z81z&quot;&gt;Experience using AI and automation to improve program execution, customer insights, synthesis, reporting, or operating efficiency.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Durable Skills&lt;/h2&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;AI fluency means using these tools to &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;em&gt;amplify&lt;/em&gt;&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; human judgment, not replace it. We believe people with these skills will thrive as work and technology&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;continue to evolve:&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Awareness:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;U&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;nderstand &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;yourself&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; and others&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
